<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class TeacherCuratorController extends Controller{
 private function group(Request $r,$id){$u=$r->user();$g=DB::table('study_groups')->find($id);abort_if(!$g,404);abort_unless($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')||($u->teacher_id&&$g->curator_teacher_id==$u->teacher_id),403);return $g;}
 public function index(Request $r){$u=$r->user();abort_unless($u->teacher_id||$u->isSuperAdmin()||$u->hasRole('admin'),403);$q=DB::table('study_groups')->where('active',1);if($u->teacher_id&&!($u->isSuperAdmin()||$u->hasRole('admin')||$u->hasRole('academic_head')))$q->where('curator_teacher_id',$u->teacher_id);$groups=$q->orderBy('name')->get();return view('teacher.curator-index',compact('groups'));}
 public function plan(Request $r,$id){$g=$this->group($r,$id);$u=$r->user();$teacherId=$u->teacher_id?:$g->curator_teacher_id;$plan=DB::table('curator_work_plans')->where('study_group_id',$id)->where('teacher_id',$teacherId)->orderByDesc('id')->first();return view('teacher.curator-plan',compact('g','plan'));}
 public function planSave(Request $r,$id){$g=$this->group($r,$id);$u=$r->user();$teacherId=$u->teacher_id?:$g->curator_teacher_id;$d=$r->validate(['title'=>'required|string|max:255','content'=>'nullable|string|max:50000','status'=>'required|in:draft,active,completed']);DB::table('curator_work_plans')->updateOrInsert(['study_group_id'=>$id,'teacher_id'=>$teacherId],$d+['updated_at'=>now(),'created_at'=>now()]);return back()->with('success','План воспитательной работы сохранён');}
 public function characteristic(Request $r,$group,$student){$g=$this->group($r,$group);$s=DB::table('students')->where('id',$student)->where('current_group_id',$group)->first();abort_unless($s,404);$rows=DB::table('student_characteristics')->where('student_id',$student)->orderByDesc('prepared_on')->get();return view('teacher.student-characteristic',compact('g','s','rows'));}
 public function characteristicStore(Request $r,$group,$student){$g=$this->group($r,$group);abort_unless(DB::table('students')->where('id',$student)->where('current_group_id',$group)->exists(),404);$d=$r->validate(['request_basis'=>'nullable|string|max:500','content'=>'required|string|max:50000','prepared_on'=>'required|date']);DB::table('student_characteristics')->insert($d+['student_id'=>$student,'teacher_id'=>$r->user()->teacher_id?:$g->curator_teacher_id,'created_at'=>now(),'updated_at'=>now()]);return back()->with('success','Характеристика сохранена');}
 public function show(Request $r,$id){$g=$this->group($r,$id);$students=DB::table('students')->where('current_group_id',$id)->where('status','active')->orderBy('last_name')->orderBy('first_name')->get();$studentIds=$students->pluck('id');$orders=DB::table('academic_orders')->whereIn('student_id',$studentIds)->orderByDesc('order_date')->orderByDesc('id')->limit(20)->get();$passports=DB::table('student_social_passports')->whereIn('student_id',$studentIds)->get()->keyBy('student_id');$statusCounts=DB::table('student_social_statuses')->whereIn('student_id',$studentIds)->where('status','active')->select('student_id',DB::raw('COUNT(*) as cnt'))->groupBy('student_id')->pluck('cnt','student_id');$supportCounts=DB::table('student_social_supports')->whereIn('student_id',$studentIds)->where('status','active')->select('student_id',DB::raw('COUNT(*) as cnt'))->groupBy('student_id')->pluck('cnt','student_id');$followupCounts=DB::table('student_social_followups')->whereIn('student_id',$studentIds)->where('status','active')->select('student_id',DB::raw('COUNT(*) as cnt'))->groupBy('student_id')->pluck('cnt','student_id');$socialSummary=['passports'=>$passports->count(),'statuses'=>$statusCounts->sum(),'supports'=>$supportCounts->sum(),'followups'=>$followupCounts->sum()];return view('teacher.curator-show',compact('g','students','orders','passports','statusCounts','supportCounts','followupCounts','socialSummary'));}
}